#!/usr/bin/env bash
set -euo pipefail

# Downloads pinned versions of hls.js, Leaflet, MarkerCluster, and MapLibre and
# updates version query params and integrity hashes so served assets match.
# Also generates bundleHashes.go for the CSP header.

LEAFLET_VERSION="1.9.4"
MARKERCLUSTER_VERSION="2.0.0"
HLSJS_VERSION="1.7.4"
MAPLIBRE_VERSION="5.6.2"

# Directories to place downloaded files
LEAFLET_DIR="leaflet"
HLSJS_DIR="hlsjs"
MAPLIBRE_DIR="maplibre"
TEMPLATES_JS_DIR="templates/assets/js"

mkdir -p "$LEAFLET_DIR" "$HLSJS_DIR" "$MAPLIBRE_DIR"

_download() {
  local url="$1" dest="$2"
  echo "Downloading $url -> $dest"
  curl --fail --location --retry 3 --retry-delay 2 --silent --show-error -o "$dest" "$url"

  # If this is a JS file, remove any sourceMappingURL comment lines
  # without leaving an empty line where the comment was.
  if [[ "$dest" == *.js ]]; then
    if [ -f "$dest" ]; then
      tmp="$(mktemp "${TMPDIR:-/tmp}/remove-sourcemap.XXXXXX")" || return
      # Filter out lines that start with optional whitespace then '//# sourceMappingURL='
      awk '!/^[ \t]*\/\/# sourceMappingURL=/' "$dest" > "$tmp"
      # Preserve permissions and replace original file
      chmod --reference="$dest" "$tmp" 2>/dev/null || true
      mv -f "$tmp" "$dest"
    fi
  fi
}

# Compute base64-encoded SHA256 of a file
_sha256b64() {
  sha256sum "$1" | awk '{print $1}' | xxd -r -p | base64 -w0
}

# Download Leaflet JS and CSS
_download "https://unpkg.com/leaflet@${LEAFLET_VERSION}/dist/leaflet.js" "${LEAFLET_DIR}/leaflet.js"
_download "https://unpkg.com/leaflet@${LEAFLET_VERSION}/dist/leaflet.css" "${LEAFLET_DIR}/leaflet.css"

# Download Leaflet MarkerCluster plugin files
_download "https://unpkg.com/leaflet.markercluster@${MARKERCLUSTER_VERSION}/dist/leaflet.markercluster.js" "${LEAFLET_DIR}/markercluster.js"
_download "https://unpkg.com/leaflet.markercluster@${MARKERCLUSTER_VERSION}/dist/MarkerCluster.css" "${LEAFLET_DIR}/markercluster.css"
_download "https://unpkg.com/leaflet.markercluster@${MARKERCLUSTER_VERSION}/dist/MarkerCluster.Default.css" "${LEAFLET_DIR}/markercluster.default.css"

# Download hls.js
_download "https://unpkg.com/hls.js@${HLSJS_VERSION}/dist/hls.min.js" "${HLSJS_DIR}/hls.js"

# Download MapLibre GL JS's CSP-compatible bundle and worker for vector maps
_download "https://unpkg.com/maplibre-gl@${MAPLIBRE_VERSION}/dist/maplibre-gl-csp.js" "${MAPLIBRE_DIR}/maplibre-gl.js"
_download "https://unpkg.com/maplibre-gl@${MAPLIBRE_VERSION}/dist/maplibre-gl-csp-worker.js" "${MAPLIBRE_DIR}/maplibre-gl-worker.js"
_download "https://unpkg.com/maplibre-gl@${MAPLIBRE_VERSION}/dist/maplibre-gl.css" "${MAPLIBRE_DIR}/maplibre-gl.css"

# Keep the canvas at the map's CSS dimensions. The upstream implementation
# writes dynamic inline dimensions, which are incompatible with GoBlog's CSP.
sed -i 's/,this\._canvas\.style\.width=`${t}px`,this\._canvas\.style\.height=`${e}px`//' "${MAPLIBRE_DIR}/maplibre-gl.js"

# Remove sourceMappingURL comment lines from JS files in the downloaded files.


# Compute SHA256 hashes and generate bundleHashes.go
LEAFLET_JS_HASH=$(_sha256b64 "${LEAFLET_DIR}/leaflet.js")
MARKERCLUSTER_JS_HASH=$(_sha256b64 "${LEAFLET_DIR}/markercluster.js")
HLSJS_HASH=$(_sha256b64 "${HLSJS_DIR}/hls.js")
MAPLIBRE_JS_HASH=$(_sha256b64 "${MAPLIBRE_DIR}/maplibre-gl.js")

echo "Generating bundleHashes.go"
cat > bundleHashes.go << BUNDLEHASHESEOF
// Code generated by bundle-assets.sh; DO NOT EDIT.

package main

var bundleHashes = map[string]string{
	"leaflet/leaflet.js":       "${LEAFLET_JS_HASH}",
	"leaflet/markercluster.js": "${MARKERCLUSTER_JS_HASH}",
	"hlsjs/hls.js":             "${HLSJS_HASH}",
	"maplibre/maplibre-gl.js":  "${MAPLIBRE_JS_HASH}",
}
BUNDLEHASHESEOF


# Update version query params and integrity hashes in JS files

# Helper: remove existing integrity lines and insert new ones after matching lines
_update_integrity_file() {
  local file="$1"; shift
  sed -i "/integrity = 'sha256-/d" "$file"
  local pairs=("$@")
  local idx
  for ((idx=${#pairs[@]}-3; idx>=0; idx-=3)); do
    local match="${pairs[$idx]}"
    local hash="${pairs[$((idx+1))]}"
    local indent="${pairs[$((idx+2))]}"
    sed -i "s|.*${match}.*|&\n${indent}integrity = 'sha256-${hash}'|" "$file"
  done
}

if [ -f "${TEMPLATES_JS_DIR}/video.js" ]; then
  echo "Updating ${TEMPLATES_JS_DIR}/video.js with hls.js version ${HLSJS_VERSION}"
  sed -E -i "s|(/-/hlsjs/hls\.js\?v=)[^'\"[:space:]]+|\\1${HLSJS_VERSION}|g" "${TEMPLATES_JS_DIR}/video.js"
  _update_integrity_file "${TEMPLATES_JS_DIR}/video.js" \
    "/-/hlsjs/hls\.js" "${HLSJS_HASH}" "    script."
fi

if [ -f "${TEMPLATES_JS_DIR}/geomap.js" ]; then
  echo "Updating ${TEMPLATES_JS_DIR}/geomap.js with leaflet ${LEAFLET_VERSION} and markercluster ${MARKERCLUSTER_VERSION}"
  sed -E -i \
    -e "s|(/-/leaflet/leaflet\.css\?v=)[^'\"[:space:]]+|\\1${LEAFLET_VERSION}|g" \
    -e "s|(/-/leaflet/leaflet\.js\?v=)[^'\"[:space:]]+|\\1${LEAFLET_VERSION}|g" \
    -e "s|(/-/leaflet/markercluster\.css\?v=)[^'\"[:space:]]+|\\1${MARKERCLUSTER_VERSION}|g" \
    -e "s|(/-/leaflet/markercluster\.default\.css\?v=)[^'\"[:space:]]+|\\1${MARKERCLUSTER_VERSION}|g" \
    -e "s|(/-/leaflet/markercluster\.js\?v=)[^'\"[:space:]]+|\\1${MARKERCLUSTER_VERSION}|g" \
    "${TEMPLATES_JS_DIR}/geomap.js"
  echo "Updating ${TEMPLATES_JS_DIR}/geomap.js with MapLibre GL JS ${MAPLIBRE_VERSION}"
  sed -E -i "s#(/-/maplibre/maplibre-gl(-worker)?\.(css|js)\?v=)[^'\"[:space:]]+#\\1${MAPLIBRE_VERSION}#g" "${TEMPLATES_JS_DIR}/geomap.js"
  _update_integrity_file "${TEMPLATES_JS_DIR}/geomap.js" \
    "/-/leaflet/leaflet\.js" "${LEAFLET_JS_HASH}" "    script." \
    "/-/leaflet/markercluster\.js" "${MARKERCLUSTER_JS_HASH}" "        plugin." \
    "/-/maplibre/maplibre-gl\.js" "${MAPLIBRE_JS_HASH}" "        script."
fi

cat <<EOF
Finished downloading assets and updating templates:
  leaflet version: ${LEAFLET_VERSION}
  markercluster version: ${MARKERCLUSTER_VERSION}
  hls.js version: ${HLSJS_VERSION}
  MapLibre version: ${MAPLIBRE_VERSION}
Integrity hashes computed and written to bundleHashes.go
Files placed in:
  ${HLSJS_DIR}/
  ${MAPLIBRE_DIR}/ (CSP-compatible MapLibre bundle and worker)
  ${LEAFLET_DIR}/
JS files updated:
  ${TEMPLATES_JS_DIR}/video.js (hls.js)
  ${TEMPLATES_JS_DIR}/geomap.js (leaflet, markercluster, MapLibre)
EOF
